# 工地日志记录员：统计四行命令里 add / commit / push / status 各出现几次
cmds = []
for i in range(4):
    cmds.append(input())

add_cnt = 0
commit_cnt = 0
push_cnt = 0
status_cnt = 0

for cmd in cmds:
    if "add" in cmd:
        add_cnt += 1
    elif "commit" in cmd:
        commit_cnt += 1
    elif "push" in cmd:
        push_cnt += 1
    elif "status" in cmd:
        status_cnt += 1

